      mauticContactId: target ? id(target.id) : null,
      method: target ? 'PATCH' : 'POST',
      url: target ? `https://connect.devreemakelaardij.nl/api/contacts/${id(target.id)}/edit`
        : 'https://connect.devreemakelaardij.nl/api/contacts/new' };
  }

